import { useState } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Ticket, ArrowRight, RefreshCw } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

const DEMOS = [
  { label: "Attendee", email: "maya@eventra.test", pw: "otter-badge-comet-50" },
  { label: "Organizer", email: "jules@eventra.test", pw: "cobalt-harbor-zest-76" },
  { label: "Door", email: "sam@eventra.test", pw: "teal-lemon-quartz-62" },
];

const BARS = Array.from({ length: 46 }, (_, i) => 1 + ((i * 7 + (i % 3) * 5) % 4));

const notch = (pos: "top" | "bottom") => {
  const y = pos === "top" ? "0" : "100%";
  const g = (x: string) => `radial-gradient(circle 13px at ${x} ${y}, #0000 97%, #000)`;
  return {
    WebkitMaskImage: `${g("0")}, ${g("100%")}`,
    maskImage: `${g("0")}, ${g("100%")}`,
    WebkitMaskComposite: "source-in",
    maskComposite: "intersect",
  } as React.CSSProperties;
};

function GoogleG() {
  return (
    <svg viewBox="0 0 48 48" className="h-5 w-5" aria-hidden="true">
      <path fill="#EA4335" d="M24 9.5c3.5 0 6.6 1.2 9.1 3.6l6.8-6.8C35.8 2.4 30.3 0 24 0 14.6 0 6.5 5.4 2.6 13.2l7.9 6.1C12.4 13.6 17.7 9.5 24 9.5z" />
      <path fill="#4285F4" d="M46.1 24.5c0-1.6-.1-3.1-.4-4.5H24v9h12.4c-.5 2.9-2.2 5.3-4.6 6.9l7.3 5.7c4.3-4 6.8-9.9 7-17.1z" />
      <path fill="#FBBC05" d="M10.5 28.7a14.5 14.5 0 0 1 0-9.4l-7.9-6.1a24 24 0 0 0 0 21.6l7.9-6.1z" />
      <path fill="#34A853" d="M24 48c6.5 0 11.9-2.1 15.9-5.8l-7.3-5.7c-2 1.4-4.8 2.3-8.6 2.3-6.3 0-11.6-4.1-13.5-9.8l-7.9 6.1C6.5 42.6 14.6 48 24 48z" />
    </svg>
  );
}

export default function EventraAuth({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const a = app?.auth;
  const signup = a?.mode === "signup";
  const providers = a?.providers ?? [];
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [pw, setPw] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const submit = async () => {
    if (!a || busy) return;
    setBusy(true);
    setErr("");
    try {
      if (signup) await a.signUp({ email, password: pw, name: name || email.split("@")[0] });
      else await a.signIn(email, pw);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Something went wrong. Try again.");
    } finally {
      setBusy(false);
    }
  };

  const provider = async (n: string) => {
    if (!a) return;
    setErr("");
    try {
      await a.startProvider(n);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Could not start that sign-in. Try again.");
    }
  };

  const inputCls =
    "w-full rounded-xl border border-[#150A1F]/15 bg-white px-4 py-3 text-[15px] text-[#150A1F] placeholder:text-[#150A1F]/40 outline-none transition focus:border-[#FF3D7F] focus:ring-4 focus:ring-[#FF3D7F]/20";

  const beam = (left: string, color: string, dur: number, from: number, to: number) => (
    <motion.div
      className="absolute top-[-10%] h-[120%] w-[38vw] min-w-[260px] origin-top"
      style={{ left, background: `linear-gradient(180deg, ${color} 0%, transparent 75%)`, clipPath: "polygon(46% 0, 54% 0, 100% 100%, 0 100%)", filter: "blur(10px)" }}
      initial={{ rotate: from }}
      animate={reduce ? { rotate: from } : { rotate: [from, to, from] }}
      transition={{ duration: dur, repeat: Infinity, ease: "easeInOut" }}
    />
  );

  return (
    <div className="relative min-h-screen w-full overflow-hidden bg-[#07040D] text-white">
      <div className="pointer-events-none absolute inset-0">
        {beam("-6%", "rgba(255,61,127,0.45)", 11, -18, 14)}
        {beam("34%", "rgba(176,107,255,0.35)", 14, 12, -16)}
        {beam("66%", "rgba(255,122,89,0.32)", 17, -10, 20)}
        <div className="absolute inset-x-0 bottom-0 h-[38%] bg-gradient-to-t from-[#FF3D7F]/25 via-[#6D3BFF]/10 to-transparent" />
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,transparent_30%,#07040D_95%)]" />
      </div>

      <div className="relative mx-auto flex min-h-screen w-full max-w-[460px] flex-col justify-center px-4 py-8 sm:max-w-[520px]">
        <motion.div
          initial={reduce ? false : { opacity: 0, y: 60, rotate: -3 }}
          animate={reduce ? undefined : { opacity: 1, y: 0, rotate: 0 }}
          transition={{ type: "spring", stiffness: 80, damping: 14 }}
          className="drop-shadow-[0_30px_60px_rgba(0,0,0,0.75)]"
        >
          <motion.div animate={reduce ? undefined : { y: [0, -6, 0] }} transition={{ duration: 7, repeat: Infinity, ease: "easeInOut" }}>
            <div style={notch("bottom")} className="relative overflow-hidden rounded-t-[26px] bg-gradient-to-br from-[#FF3D7F] via-[#E0307F] to-[#7B3BFF] px-6 pb-7 pt-5">
              <div className="flex items-center justify-between text-[11px] font-bold uppercase tracking-[0.25em] text-white/85">
                <span className="flex items-center gap-1.5"><Ticket className="h-4 w-4" />Eventra</span>
                <span>Admit one</span>
              </div>
              <h1 className="mt-3 text-[56px] font-black uppercase leading-[0.82] tracking-tighter sm:text-[72px]">
                Own the<br /><span className="text-[#07040D]">night.</span>
              </h1>
              <div className="mt-4 flex gap-5 text-[10px] font-bold uppercase tracking-[0.2em] text-white/80">
                <span>Doors 20:00</span><span>Row ∞</span><span>Seat: front</span>
              </div>
            </div>
            <div className="relative h-0">
              <div className="absolute inset-x-5 top-0 border-t-2 border-dashed border-white/25" />
            </div>
            <div style={notch("top")} className="rounded-b-[26px] bg-[#FBF7F2] px-6 pb-5 pt-7 text-[#150A1F]">
              {a?.canSignUp !== false ? (
                <div className="mb-4 flex rounded-full p-1" style={{ background: "rgba(21,10,31,0.08)" }}>
                  {[{ k: false, t: "Returning" }, { k: true, t: "New here" }].map((o) => (
                    <button key={o.t} type="button" onClick={() => a?.setMode(o.k ? "signup" : "login")} className="relative flex-1 rounded-full py-2 text-sm font-bold" style={{ color: signup === o.k ? "#fff" : "rgba(21,10,31,0.55)" }}>
                      {signup === o.k && <motion.span layoutId="eventra-tab" className="absolute inset-0 rounded-full bg-[#150A1F]" transition={{ type: "spring", stiffness: 400, damping: 30 }} />}
                      <span className="relative">{o.t}</span>
                    </button>
                  ))}
                </div>
              ) : null}

              <form onSubmit={(e) => { e.preventDefault(); void submit(); }} className="space-y-2.5">
                <AnimatePresence initial={false}>
                  {signup && (
                    <motion.div key="n" initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} className="overflow-hidden">
                      <input aria-label="Name" type="text" placeholder="Your name" value={name} onChange={(e) => setName(e.target.value)} className={inputCls} />
                    </motion.div>
                  )}
                </AnimatePresence>
                <input aria-label="Email" type="email" autoComplete="email" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} className={inputCls} />
                <input aria-label="Password" type="password" autoComplete={signup ? "new-password" : "current-password"} placeholder="Password" value={pw} onChange={(e) => setPw(e.target.value)} className={inputCls} />
                <AnimatePresence>
                  {err && <motion.p initial={{ opacity: 0, y: -6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} role="alert" className="rounded-xl bg-red-500/15 px-3 py-2 text-sm text-red-700">{err}</motion.p>}
                </AnimatePresence>
                <motion.button type="submit" whileTap={{ scale: 0.97 }} whileHover={{ scale: 1.02 }} className="flex w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-[#FF3D7F] to-[#FF6A3D] py-3.5 text-base font-black uppercase tracking-wide text-white shadow-[0_10px_30px_-8px_rgba(255,61,127,0.8)]">
                  {busy ? <RefreshCw className="h-5 w-5 animate-spin" /> : null}
                  {signup ? "Create account" : "Sign in"}
                  {!busy && <ArrowRight className="h-5 w-5" />}
                </motion.button>
              </form>

              {providers.length > 0 && (
                <div className="mt-4">
                  <div className="mb-3 flex items-center gap-3 text-[11px] font-bold uppercase tracking-[0.25em] text-[#150A1F]/40">
                    <span className="h-px flex-1 bg-[#150A1F]/15" />or<span className="h-px flex-1 bg-[#150A1F]/15" />
                  </div>
                  <div className="space-y-2">
                    {providers.map((p) => (
                      <motion.button key={p.name} type="button" whileTap={{ scale: 0.97 }} onClick={() => void provider(p.name)} className="flex w-full items-center justify-center gap-3 rounded-xl border border-[#150A1F]/20 bg-white py-3 text-[15px] font-bold text-[#150A1F]">
                        {p.name === "google" ? <GoogleG /> : null}
                        Continue with {p.label}
                      </motion.button>
                    ))}
                  </div>
                </div>
              )}

              {!signup && (
                <div className="mt-4 flex flex-wrap items-center justify-center gap-2">
                  <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#150A1F]/45">Demo</span>
                  {DEMOS.map((d) => (
                    <motion.button key={d.label} type="button" whileTap={{ scale: 0.93 }} onClick={() => { setEmail(d.email); setPw(d.pw); }} className="rounded-full border border-[#150A1F]/20 px-3 py-1.5 text-xs font-bold text-[#150A1F]/80 hover:border-[#FF3D7F] hover:text-[#FF3D7F]">{d.label}</motion.button>
                  ))}
                </div>
              )}

              <div className="mt-5 flex h-9 items-stretch justify-center gap-[2px] opacity-80" aria-hidden="true">
                {BARS.map((w, i) => (
                  <i key={i} className="block bg-[#150A1F]" style={{ width: w }} />
                ))}
              </div>
              <p className="mt-1 text-center font-mono text-[9px] uppercase tracking-[0.35em] text-[#150A1F]/40">EVT-0001 · no refunds on a good time</p>
            </div>
          </motion.div>
        </motion.div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { motion, AnimatePresence, useReducedMotion, useScroll, useTransform } from "motion/react";
import { Ticket, Flame, MapPin, Calendar, ArrowRight, LogOut, Bell, Zap } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
const s = (v: unknown) => String(v ?? "");
const n = (v: unknown) => Number(v) || 0;
const day = (v: unknown) => {
  const d = new Date(s(v));
  if (isNaN(d.getTime())) return { wd: "TBA", d: "--", m: "", t: "" };
  return {
    wd: d.toLocaleDateString("en-US", { weekday: "short", timeZone: "UTC" }),
    d: d.toLocaleDateString("en-US", { day: "numeric", timeZone: "UTC" }),
    m: d.toLocaleDateString("en-US", { month: "short", timeZone: "UTC" }),
    t: d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", timeZone: "UTC" }),
  };
};
const GENRES = ["all", "electronic", "rock", "hiphop", "pop", "jazz", "indie", "festival"];
const GRAD = ["from-[#FF3D7F] to-[#6D3BFF]", "from-[#FF8A3D] to-[#FF3D7F]", "from-[#22D3EE] to-[#6D3BFF]", "from-[#B6FF3B] to-[#22D3EE]"];

function Nav({ app, active }: { app?: AppHandle; active: "discover" | "tickets" }) {
  const items = [
    { k: "discover", label: "Discover", Icon: Flame, to: "/discover" },
    { k: "tickets", label: "My tickets", Icon: Ticket, to: "/tickets" },
  ] as const;
  return (
    <>
      <header className="sticky top-0 z-40 border-b border-white/10 bg-[#09050F]/80 backdrop-blur-xl">
        <div className="mx-auto flex h-16 max-w-7xl items-center justify-between px-5">
          <button type="button" onClick={() => app?.navigate("/discover")} className="flex items-center gap-2 text-lg font-black uppercase tracking-tight">
            <span className="grid h-8 w-8 place-items-center rounded-xl bg-[#FF3D7F] shadow-[0_0_24px_rgba(255,61,127,0.7)]"><Ticket className="h-4 w-4" /></span>
            Eventra
          </button>
          <nav className="hidden items-center gap-1 md:flex">
            {items.map((i) => (
              <button key={i.k} type="button" onClick={() => app?.navigate(i.to)} className="relative rounded-full px-4 py-2 text-sm font-semibold" style={{ color: active === i.k ? "#fff" : "rgba(255,255,255,0.55)" }}>
                {active === i.k && <motion.span layoutId="navpill" className="absolute inset-0 rounded-full bg-white/10" />}
                <span className="relative">{i.label}</span>
              </button>
            ))}
          </nav>
          <div className="flex items-center gap-3">
            <span className="hidden text-sm text-white/60 sm:block">{app?.user.name}</span>
            <button type="button" aria-label="Sign out" onClick={() => app?.auth.signOut()} className="grid h-9 w-9 place-items-center rounded-full border border-white/15 bg-white/5 text-white/70 hover:text-white"><LogOut className="h-4 w-4" /></button>
          </div>
        </div>
      </header>
      <nav className="fixed inset-x-3 bottom-3 z-40 flex rounded-full border border-white/10 bg-[#140B22]/90 p-1.5 shadow-[0_20px_50px_rgba(0,0,0,0.6)] backdrop-blur-xl md:hidden">
        {items.map((i) => (
          <button key={i.k} type="button" onClick={() => app?.navigate(i.to)} className="relative flex flex-1 items-center justify-center gap-2 rounded-full py-3 text-sm font-bold" style={{ color: active === i.k ? "#fff" : "rgba(255,255,255,0.5)" }}>
            {active === i.k && <motion.span layoutId="tabpill" className="absolute inset-0 rounded-full bg-[#FF3D7F]" transition={{ type: "spring", stiffness: 400, damping: 32 }} />}
            <i.Icon className="relative h-4 w-4" /><span className="relative">{i.label}</span>
          </button>
        ))}
      </nav>
    </>
  );
}

function Cap({ sold, cap }: { sold: number; cap: number }) {
  const pct = cap > 0 ? Math.min(100, Math.round((sold / cap) * 100)) : 0;
  const out = sold >= cap && cap > 0;
  return (
    <div>
      <div className="h-1.5 w-full overflow-hidden rounded-full bg-white/15">
        <motion.div className="h-full rounded-full" style={{ background: out ? "#ef4444" : pct > 85 ? "linear-gradient(90deg,#FF8A3D,#FF3D7F)" : "linear-gradient(90deg,#FF3D7F,#B06BFF)" }} initial={{ width: 0 }} animate={{ width: pct + "%" }} transition={{ duration: 1, ease: "easeOut" }} />
      </div>
      <div className="mt-1.5 flex justify-between text-[11px] font-semibold uppercase tracking-wider text-white/60">
        <span>{out ? "Sold out" : pct > 85 ? "Almost gone" : pct + "% sold"}</span>
        <span>{sold.toLocaleString("en-US")} / {cap.toLocaleString("en-US")}</span>
      </div>
    </div>
  );
}

function PosterCard({ ev, i, app, tiers }: { ev: R; i: number; app?: AppHandle; tiers: R[] }) {
  const reduce = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start end", "end start"] });
  const y = useTransform(scrollYProgress, [0, 1], ["-9%", "9%"]);
  const dt = day(ev.starts_at);
  const out = n(ev.sold) >= n(ev.capacity);
  const from = tiers.filter((t) => s(t.event_id) === s(ev.id)).reduce((m, t) => Math.min(m, n(t.price)), 9999);
  return (
    <motion.div
      ref={ref}
      layout
      initial={{ opacity: 0, y: 50 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-40px" }}
      exit={{ opacity: 0, scale: 0.9 }}
      transition={{ type: "spring", stiffness: 90, damping: 16, delay: (i % 3) * 0.07 }}
      whileHover={reduce ? undefined : { y: -6 }}
      whileTap={{ scale: 0.97 }}
      onClick={() => app?.navigate("/event/" + s(ev.id))}
      className="group relative cursor-pointer overflow-hidden rounded-[28px] border border-white/10 bg-[#140B22] shadow-[0_24px_60px_-20px_rgba(0,0,0,0.9)]"
    >
      <div className="relative aspect-[4/5] overflow-hidden">
        <motion.img src={s(ev.poster)} alt={s(ev.title)} style={reduce ? undefined : { y, scale: 1.2 }} className="absolute inset-0 h-full w-full object-cover" />
        <div className={"absolute inset-0 bg-gradient-to-br opacity-30 mix-blend-overlay " + GRAD[i % GRAD.length]} />
        <div className="absolute inset-0 bg-gradient-to-t from-[#09050F] via-[#09050F]/40 to-transparent" />
        <div className="absolute left-4 top-4 rounded-2xl bg-white px-3 py-2 text-center text-[#09050F] shadow-lg">
          <div className="text-[10px] font-bold uppercase tracking-widest text-[#FF3D7F]">{dt.m}</div>
          <div className="text-2xl font-black leading-none">{dt.d}</div>
        </div>
        <div className="absolute right-4 top-4 rounded-full bg-black/50 px-3 py-1 text-[11px] font-bold uppercase tracking-widest backdrop-blur">{s(ev.genre)}</div>
        {out && <div className="absolute inset-x-0 top-1/2 -rotate-6 bg-[#ef4444] py-1 text-center text-sm font-black uppercase tracking-[0.4em]">Sold out</div>}
        <div className="absolute inset-x-0 bottom-0 p-5">
          <h3 className="text-3xl font-black uppercase leading-[0.95] tracking-tight">{s(ev.title)}</h3>
          <p className="mt-1 flex items-center gap-1.5 text-sm text-white/70"><MapPin className="h-3.5 w-3.5 text-[#FF3D7F]" />{s(ev.venue)} · {s(ev.city)}</p>
        </div>
      </div>
      <div className="space-y-3 p-5">
        <Cap sold={n(ev.sold)} cap={n(ev.capacity)} />
        <div className="flex items-center justify-between">
          <span className="text-sm text-white/60">{dt.wd} · {dt.t}</span>
          <span className="flex items-center gap-1 text-sm font-bold text-[#FF3D7F]">{out ? "Sold out" : from < 9999 ? "from $" + from : "Tickets"}<ArrowRight className="h-4 w-4 transition group-hover:translate-x-1" /></span>
        </div>
      </div>
    </motion.div>
  );
}

export default function EventraDiscover({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [genre, setGenre] = useState("all");
  useEffect(() => (app ? app.live("event") : undefined), [app]);
  const events = useMemo(() => ((app?.rows("event") ?? []) as R[]).slice().sort((a, b) => s(a.starts_at).localeCompare(s(b.starts_at))), [app]);
  const tiers = (app?.rows("ticket_tier") ?? []) as R[];
  const reminders = (app?.rows("reminder") ?? []) as R[];
  const loading = app?.loading("event") && events.length === 0;
  const shown = events.filter((e) => genre === "all" || s(e.genre) === genre);
  const hero = events.find((e) => n(e.sold) < n(e.capacity)) ?? events[0];
  const { scrollY } = useScroll();
  const heroY = useTransform(scrollY, [0, 500], [0, 120]);
  const hd = hero ? day(hero.starts_at) : null;
  return (
    <div className="min-h-screen bg-[#09050F] pb-28 text-white md:pb-16">
      <Nav app={app} active="discover" />
      {hero && hd && (
        <section className="relative isolate overflow-hidden">
          <motion.img src={s(hero.poster)} alt="" style={reduce ? undefined : { y: heroY }} className="absolute inset-0 -z-10 h-[115%] w-full object-cover opacity-60" />
          <div className="absolute inset-0 -z-10 bg-gradient-to-t from-[#09050F] via-[#09050F]/60 to-[#09050F]/20" />
          <div className="absolute inset-0 -z-10 bg-gradient-to-r from-[#FF3D7F]/30 to-transparent" />
          <div className="mx-auto max-w-7xl px-5 pb-12 pt-20 md:pb-20 md:pt-32">
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="mb-4 inline-flex items-center gap-2 rounded-full bg-[#FF3D7F] px-3 py-1 text-xs font-black uppercase tracking-widest"><Zap className="h-3.5 w-3.5" />Next up · {hd.wd} {hd.m} {hd.d}</motion.div>
            <motion.h1 style={{ lineHeight: 0.88 }} initial={{ opacity: 0, y: 40 }} animate={{ opacity: 1, y: 0 }} transition={{ type: "spring", stiffness: 70, damping: 15, delay: 0.1 }} className="max-w-4xl break-words text-[56px] font-black uppercase leading-[0.85] tracking-tighter sm:text-8xl lg:text-[140px]">{s(hero.title)}</motion.h1>
            <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }} className="mt-4 max-w-lg text-lg text-white/75">{s(hero.tagline)}</motion.p>
            <div className="mt-6 flex flex-wrap items-center gap-4">
              <motion.button type="button" whileTap={{ scale: 0.95 }} whileHover={{ scale: 1.04 }} onClick={() => app?.navigate("/event/" + s(hero.id))} className="flex items-center gap-2 rounded-full bg-white px-7 py-4 text-base font-black uppercase tracking-wide text-[#09050F] shadow-[0_10px_40px_rgba(255,61,127,0.5)]">Get tickets <ArrowRight className="h-5 w-5" /></motion.button>
              <span className="flex items-center gap-2 text-sm text-white/70"><Calendar className="h-4 w-4" />{hd.t} · {s(hero.venue)}, {s(hero.city)}</span>
            </div>
            <div className="mt-8 max-w-md"><Cap sold={n(hero.sold)} cap={n(hero.capacity)} /></div>
          </div>
        </section>
      )}

      <main className="mx-auto max-w-7xl px-5">
        <AnimatePresence>
          {reminders.length > 0 && (
            <motion.button type="button" onClick={() => app?.navigate("/tickets")} initial={{ opacity: 0, y: -12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="mt-6 flex w-full items-center gap-3 rounded-3xl border border-[#FF3D7F]/40 bg-[#FF3D7F]/10 p-4 text-left">
              <span className="grid h-10 w-10 shrink-0 place-items-center rounded-2xl bg-[#FF3D7F]"><Bell className="h-5 w-5" /></span>
              <span><span className="block font-bold">{s(reminders[0].title)}</span><span className="block text-sm text-white/70">{s(reminders[0].message)}</span></span>
            </motion.button>
          )}
        </AnimatePresence>

