}

import { useEffect, useRef, useState } from "react";
import { motion, AnimatePresence, animate, useReducedMotion, useScroll, useTransform } from "motion/react";
import { QRCodeSVG } from "qrcode.react";
import { ArrowLeft, MapPin, Clock, Ticket, Plus, Check, X, AlertTriangle, Users, Mic } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
const s = (v: unknown) => String(v ?? "");
const n = (v: unknown) => Number(v) || 0;
const fmt = (v: unknown, o: Intl.DateTimeFormatOptions) => {
  const d = new Date(s(v));
  return isNaN(d.getTime()) ? "TBA" : d.toLocaleString("en-US", { ...o, timeZone: "UTC" });
};
const ALPHA = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
const rnd = (k: number) => Array.from({ length: k }, () => ALPHA[Math.floor(Math.random() * ALPHA.length)]).join("");
const wait = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

function Counter({ value }: { value: number }) {
  const [d, setD] = useState(value);
  const from = useRef(value);
  useEffect(() => {
    const c = animate(from.current, value, { duration: 0.9, ease: "easeOut", onUpdate: (v) => setD(Math.round(v)) });
    from.current = value;
    return () => c.stop();
  }, [value]);
  return <>{d.toLocaleString("en-US")}</>;
}

export default function EventraEvent({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const id = app?.params.id ?? "";
  useEffect(() => (app ? app.live("event") : undefined), [app]);
  const ev = ((app?.rows("event") ?? []) as R[]).find((e) => s(e.id) === id);
  const tiers = ((app?.rows("ticket_tier") ?? []) as R[]).filter((t) => s(t.event_id) === id).sort((a, b) => n(a.price) - n(b.price));
  const [tierId, setTierId] = useState("");
  const [qty, setQty] = useState(1);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [done, setDone] = useState<string[]>([]);
  const { scrollY } = useScroll();
  const y = useTransform(scrollY, [0, 500], [0, 100]);
  const tier = tiers.find((t) => s(t.id) === tierId) ?? tiers[0];
  const sold = n(ev?.sold);
  const cap = n(ev?.capacity);
  const left = Math.max(0, cap - sold);
  const out = !!ev && left <= 0;
  const pct = cap > 0 ? Math.min(100, (sold / cap) * 100) : 0;
  const maxQty = Math.max(1, Math.min(4, left));
  const total = tier ? n(tier.price) * qty : 0;
  const lineup = s(ev?.lineup).split("\n").filter(Boolean).map((l) => { const [a, b] = l.split("|"); return { a: a ?? "", t: b ?? "" }; });

  useEffect(() => { if (qty > maxQty) setQty(maxQty); }, [maxQty, qty]);

  const buy = async () => {
    if (!app || !ev || !tier || busy || out) return;
    setBusy(true);
    setErr("");
    const codes: string[] = [];
    try {
      for (let i = 0; i < qty; i++) {
        const code = "EVT-" + rnd(4) + "-" + rnd(4);
        await app.create("ticket", { code, event_id: s(ev.id), tier_id: s(tier.id), attendee_id: app.me("attendee") ?? "", organizer_id: s(ev.organizer_id), event_title: s(ev.title), tier_name: s(tier.name), holder_name: app.user.name || "Guest", price: n(tier.price), used: false });
        codes.push(code);
        if (i < qty - 1) await wait(700);
      }
      setDone(codes);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Could not complete the purchase.");
      if (codes.length) setDone(codes);
    } finally {
      setBusy(false);
    }
  };

  if (!ev) {
    return (
      <div className="grid min-h-screen place-items-center bg-[#09050F] px-5 text-white">
        <div className="w-full max-w-md animate-pulse space-y-4"><div className="h-64 rounded-3xl bg-white/5" /><div className="h-8 w-2/3 rounded-xl bg-white/5" /><div className="h-24 rounded-3xl bg-white/5" /></div>
      </div>
    );
  }

  const buyBtn = (cls: string) => (
    <motion.button type="button" disabled={busy || out || !tier} whileTap={{ scale: 0.95 }} whileHover={{ scale: 1.03 }} onClick={() => void buy()} className={"items-center justify-center gap-2 rounded-full px-7 py-4 text-base font-black uppercase tracking-wide shadow-[0_12px_40px_-8px_rgba(255,61,127,0.8)] disabled:opacity-60 " + cls} style={{ background: out ? "#3b2a4d" : "linear-gradient(90deg,#FF3D7F,#FF6A3D)" }}>
      {out ? "Sold out" : busy ? "Securing…" : "Buy " + qty + (qty > 1 ? " tickets" : " ticket") + " · $" + total}
    </motion.button>
  );

  return (
    <div className="min-h-screen bg-[#09050F] pb-36 text-white lg:pb-16">
      <section className="relative isolate h-[58vh] min-h-[380px] overflow-hidden lg:h-[520px]">
        <motion.img src={s(ev.poster)} alt={s(ev.title)} style={reduce ? undefined : { y }} className="absolute inset-0 -z-10 h-[120%] w-full object-cover" />
        <div className="absolute inset-0 -z-10 bg-gradient-to-t from-[#09050F] via-[#09050F]/50 to-black/30" />
