          <motion.h1 initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ type: "spring", stiffness: 80, damping: 16 }} className="mt-3 break-words text-5xl font-black uppercase leading-[0.88] tracking-tighter sm:text-7xl lg:text-8xl">{s(ev.title)}</motion.h1>
