        </div>
      </section>

      <div className="mx-auto grid max-w-6xl gap-8 px-5 pt-6 lg:grid-cols-[1fr_400px]">
        <div className="space-y-8">
          <div className="grid grid-cols-2 gap-3">
            <div className="rounded-3xl border border-white/10 bg-white/5 p-4"><Clock className="mb-2 h-5 w-5 text-[#FF3D7F]" /><div className="font-bold">{fmt(ev.starts_at, { weekday: "long", month: "short", day: "numeric" })}</div><div className="text-sm text-white/60">{fmt(ev.starts_at, { hour: "numeric", minute: "2-digit" })}</div></div>
            <div className="rounded-3xl border border-white/10 bg-white/5 p-4"><MapPin className="mb-2 h-5 w-5 text-[#FF3D7F]" /><div className="font-bold">{s(ev.venue)}</div><div className="text-sm text-white/60">{s(ev.city)}</div></div>
          </div>

          <div className="rounded-3xl border border-white/10 bg-gradient-to-br from-white/[0.07] to-white/[0.02] p-5">
