            <div className="flex items-center gap-3"><Clock className="h-4 w-4 text-[#FF3D7F]" /><div><div className="text-[10px] uppercase tracking-widest text-white/40">When</div><div className="font-bold">{fmt(ev?.starts_at, { weekday: "long", month: "long", day: "numeric", hour: "numeric", minute: "2-digit" })}</div></div></div>
            <div className="flex items-center gap-3"><MapPin className="h-4 w-4 text-[#FF3D7F]" /><div><div className="text-[10px] uppercase tracking-widest text-white/40">Where</div><div className="font-bold">{s(ev?.venue)}, {s(ev?.city)}</div></div></div>
            <div className="flex items-center gap-3"><Ticket className="h-4 w-4 text-[#FF3D7F]" /><div><div className="text-[10px] uppercase tracking-widest text-white/40">Tier · Paid</div><div className="font-bold">{s(tk.tier_name)} · ${n(tk.price)}</div></div></div>
          </div>
          {used && tk.checked_in_at ? <p className="mt-4 text-xs text-white/50">Scanned {fmt(tk.checked_in_at, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" })} UTC</p> : null}
          <motion.button type="button" whileTap={{ scale: 0.95 }} onClick={(e) => { e.stopPropagation(); setWallet(true); }} className="absolute inset-x-6 bottom-6 flex items-center justify-center gap-2 rounded-full bg-black py-4 text-sm font-bold ring-1 ring-white/25">
            <AnimatePresence mode="wait">
              {wallet ? <motion.span key="a" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} className="flex items-center gap-2 text-[#B6FF3B]"><Check className="h-4 w-4" />Added to Wallet</motion.span> : <motion.span key="b" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} className="flex items-center gap-2"><Wallet className="h-4 w-4" />Add to Wallet</motion.span>}
            </AnimatePresence>
          </motion.button>
        </div>
      </motion.div>
    </motion.div>
  );
}

